import ansible.utils.display
import ansible.utils.unsafe_proxy as unsafe_proxy


def test_unsafe_proxy_wraps_strings_and_reports_deprecation(monkeypatch):
    calls = []

    class FakeDisplay:
        def deprecated(self, *args, **kwargs):
            calls.append((args, kwargs))

    monkeypatch.setattr(ansible.utils.display, "Display", FakeDisplay)

    result = unsafe_proxy.UnsafeProxy("hello")

    assert isinstance(result, unsafe_proxy.AnsibleUnsafeText)
    assert result == "hello"
    assert calls == [
        (
            (
                "UnsafeProxy is being deprecated. Use wrap_var or "
                "AnsibleUnsafeBytes/AnsibleUnsafeText directly instead",
            ),
            {"version": "2.13", "collection_name": "ansible.builtin"},
        )
    ]


def test_unsafe_proxy_returns_existing_unsafe_object_unchanged(monkeypatch):
    calls = []

    class FakeDisplay:
        def deprecated(self, *args, **kwargs):
            calls.append((args, kwargs))

    monkeypatch.setattr(ansible.utils.display, "Display", FakeDisplay)
    unsafe_value = unsafe_proxy.AnsibleUnsafeText("already unsafe")

    result = unsafe_proxy.UnsafeProxy(unsafe_value)

    assert result is unsafe_value
    assert len(calls) == 1
    assert calls[0][1] == {
        "version": "2.13",
        "collection_name": "ansible.builtin",
    }


def test_unsafe_proxy_returns_non_string_object_unchanged(monkeypatch):
    calls = []

    class FakeDisplay:
        def deprecated(self, *args, **kwargs):
            calls.append((args, kwargs))

    monkeypatch.setattr(ansible.utils.display, "Display", FakeDisplay)
    value = object()

    result = unsafe_proxy.UnsafeProxy(value)

    assert result is value
    assert len(calls) == 1
    assert calls[0][1] == {
        "version": "2.13",
        "collection_name": "ansible.builtin",
    }
